<script setup lang="ts">
import { formatDateTime } from "../../../../../utils/format";
definePageMeta({ middleware: "project-exists" });
const route = useRoute(); const router = useRouter();
const projectId = computed(() => String(route.params.projectId)); const scheduleId = computed(() => String(route.params.scheduleId));
const schedules = useTestSchedules(projectId); const detail = shallowRef<TestScheduleDetail | null>(null); const loading = ref(true);
onMounted(async () => { detail.value = await schedules.get(scheduleId.value); loading.value = false; });
</script>
<template><div><AppPageHeader :title="detail?.schedule.name ?? '예약 상세'" description="현재 계산된 다음 실행과 불변 실행 스냅샷 이력을 확인합니다."><el-button @click="router.push(`/projects/${projectId}/schedules/${scheduleId}/edit`)">수정</el-button><el-button @click="router.push(`/projects/${projectId}/schedules`)">목록</el-button></AppPageHeader><div v-if="loading" class="form-panel"><el-skeleton :rows="7" animated /></div><el-alert v-else-if="!detail" :title="schedules.error.value ?? '예약을 찾을 수 없습니다.'" type="error" show-icon /><template v-else><section class="info-strip"><div><span>상태</span><strong><AppStatusBadge :status="detail.schedule.status" /></strong></div><div><span>스위트</span><strong>{{ detail.schedule.suiteName }}</strong></div><div><span>다음 실행</span><strong>{{ formatDateTime(detail.schedule.nextRunAt) }}</strong></div><div><span>시간대</span><strong>{{ detail.schedule.timezone }}</strong></div></section><section class="content-section"><div class="section-heading"><div><h2>실행 이력</h2><p>예약 감지, 대기, 실행, 알림 전달의 기준 기록입니다.</p></div></div><AppEmptyState v-if="!detail.executions.length" title="실행 이력이 없습니다" description="다음 실행 시각을 기다리거나 목록에서 지금 실행을 선택하세요." /><el-table v-else :data="detail.executions"><el-table-column label="상태" width="120"><template #default="scope"><AppStatusBadge :status="scope.row.status" /></template></el-table-column><el-table-column label="예정 시각" min-width="180"><template #default="scope">{{ formatDateTime(scope.row.scheduledFor) }}</template></el-table-column><el-table-column prop="trigger" label="트리거" width="190" /><el-table-column label="스위트 결과" width="130"><template #default="scope"><AppStatusBadge v-if="scope.row.suiteRunStatus" :status="scope.row.suiteRunStatus" /></template></el-table-column><el-table-column prop="regressionCount" label="회귀" width="80" /><el-table-column label="상세" width="90"><template #default="scope"><el-button text type="primary" @click="router.push(`/projects/${projectId}/schedules/${scheduleId}/executions/${scope.row.id}`)">보기</el-button></template></el-table-column></el-table></section></template></div></template>
